#!/usr/bin/env python3
"""Source regression for the nonpublishing manual-dispatch boundary.

These assertions test exact job-guard source contracts, not GitHub's hosted
expression evaluator or a completed public release.
"""
from pathlib import Path
import re

wf = Path(".github/workflows/release.yml").read_text(encoding="utf-8")
conditions = {}
for job in ("verify-preview", "publish"):
    found = re.findall(rf"(?m)^  {re.escape(job)}:\s*\n    if: (.+)$", wf)
    assert len(found) == 1, f"{job}: missing or duplicate if expression"
    conditions[job] = found[0].strip()

expected = {
    "verify-preview": "github.event_name == 'workflow_dispatch' && startsWith(github.ref, 'refs/heads/')",
    "publish": "github.event_name == 'push' && startsWith(github.ref, 'refs/tags/v')",
}
assert conditions == expected, f"release guards changed: {conditions!r}"

# These model the two simple guards above, not arbitrary expressions.
def permitted(job: str, event: str, ref: str) -> bool:
    if job == "verify-preview":
        return event == "workflow_dispatch" and ref.startswith("refs/heads/")
    if job == "publish":
        return event == "push" and ref.startswith("refs/tags/v")
    raise AssertionError(job)

cases = (
    ("workflow_dispatch", "refs/heads/feature/test", True, False),
    ("workflow_dispatch", "refs/tags/v9.9.9", False, False),
    ("push", "refs/heads/main", False, False),
    ("push", "refs/tags/v9.9.9", False, True),
    ("push", "refs/tags/unsafe-1", False, False),
    ("pull_request", "refs/pull/15/merge", False, False),
)
for event, ref, preview, publish in cases:
    assert permitted("verify-preview", event, ref) is preview, (event, ref, "preview")
    assert permitted("publish", event, ref) is publish, (event, ref, "publish")

assert wf.count("gh release create ") == 1, "publication command count changed"
publish_body = wf.split("\n  publish:\n", 1)
assert len(publish_body) == 2, "publish job section count changed"
assert "gh release create " in publish_body[1], "publish command escaped guarded job"
assert "bash .github/scripts/verify-release-attestations.sh" in publish_body[1], "release must verify attestations"
assert publish_body[1].index("bash .github/scripts/verify-release-attestations.sh") < publish_body[1].index("gh release create "), "attestations must precede release"


# Validate the actual tag/asset verification script with isolated disposable
# fixture packages; no GitHub tags, repository releases or network access.
import hashlib
import json
import os
import subprocess
import tempfile

assert wf.count("bash .github/scripts/verify-release-version.sh preview") == 1
assert wf.count("bash .github/scripts/verify-release-version.sh publish") == 1
assert publish_body[1].index("bash .github/scripts/verify-release-version.sh publish") < publish_body[1].index("bash .github/scripts/verify-release-attestations.sh")

verifier = Path(".github/scripts/verify-release-version.sh").resolve()
syntax = subprocess.run(["bash", "-n", str(verifier)], capture_output=True, text=True)
assert syntax.returncode == 0, syntax.stderr

version = "2.5.19"
assets = {
    f"OpenInternetGateway-Setup-{version}.exe": b"test windows installer",
    f"OpenInternetGateway-{version}-x86_64.AppImage": b"test linux appimage",
    f"OpenInternetGateway-{version}-amd64.deb": b"test debian package",
}
with tempfile.TemporaryDirectory(prefix="oig-release-version-fixture-") as tmp:
    work = Path(tmp)
    (work / "app").mkdir()
    (work / "release").mkdir()
    (work / "app" / "package.json").write_text(json.dumps({"version": version}), encoding="utf-8")
    for name, payload in assets.items():
        (work / "release" / name).write_bytes(payload)
    manifest = work / "release" / "SHA256SUMS.txt"

    def exercise(mode, event, ref, ok, reason=None):
        env = dict(os.environ, GITHUB_EVENT_NAME=event, GITHUB_REF=ref)
        run = subprocess.run(["bash", str(verifier), mode], cwd=work, env=env,
                             text=True, capture_output=True)
        if ok:
            assert run.returncode == 0, (mode, event, ref, run.stdout, run.stderr)
            assert "RELEASE_VERSION_ASSET_CONTRACT_PASS" in run.stdout
        else:
            assert run.returncode != 0, (mode, event, ref, "false acceptance")
            assert reason in run.stderr, (reason, run.stderr)

    exercise("preview", "workflow_dispatch", "refs/heads/security/signing", True)
    exercise("preview", "workflow_dispatch", "refs/tags/v2.5.19", False, "RELEASE_PREVIEW_EVENT_INVALID")
    exercise("preview", "push", "refs/heads/main", False, "RELEASE_PREVIEW_EVENT_INVALID")

    for name in assets:
        payload = assets[name]
        # manifest has the same relative file names as generated by release.yml
        with manifest.open("a", encoding="utf-8") as out:
            out.write(f"{hashlib.sha256(payload).hexdigest()}  {name}\n")

    exercise("publish", "push", "refs/tags/v2.5.19", True)
    exercise("publish", "workflow_dispatch", "refs/tags/v2.5.19", False, "RELEASE_TAG_PACKAGE_VERSION_MISMATCH")
    exercise("publish", "push", "refs/tags/v2.5.20", False, "RELEASE_TAG_PACKAGE_VERSION_MISMATCH")

    wrong = work / "release" / "OpenInternetGateway-2.5.18-stale.deb"
    wrong.write_bytes(b"stale")
    exercise("publish", "push", "refs/tags/v2.5.19", False, "RELEASE_UNEXPECTED_OR_DUPLICATE_ASSET_COUNT")
    wrong.unlink()

    target = work / "release" / f"OpenInternetGateway-{version}-amd64.deb"
    target.write_bytes(b"changed after hashing")
    exercise("publish", "push", "refs/tags/v2.5.19", False, "RELEASE_CHECKSUM_CONTENT_MISMATCH")
    target.write_bytes(assets[target.name])

    manifest.write_text(manifest.read_text(encoding="utf-8").replace(
        f"OpenInternetGateway-Setup-{version}.exe", "wrong-file.exe"
    ), encoding="utf-8")
    exercise("publish", "push", "refs/tags/v2.5.19", False, "RELEASE_CHECKSUM_MANIFEST_FILES_MISMATCH")

print("VERSION_ASSET_REGRESSION_PASS")

print("RELEASE_EVENT_BOUNDARY_SOURCE_CONTRACT_PASS")
